// Generated by AI (UnitTest MCP)
import assert from "node:assert/strict";
import { test } from "node:test";

import {
  completionOfferNotice,
  persistCompletionOffer,
  prepareCompletionOffer,
} from "./completion-offer.mjs";

const SESSION = "0123456789abcdef0123456789abcdef";
const NOW = 1_000_000;

/// Every name that could close a task, not just the one that used to.
///
/// ADR-0065 says this module offers and never closes, and the guard asserting
/// it named `complete_task` — which ADR-0059 retired into
/// `task_transition(to="complete")`. A guard watching a name nothing can call
/// any more cannot fail: the module could have closed a task through the new
/// verb and this test would still have passed. The deprecated alias stays in
/// the set because it still answers for one minor version, so closing through
/// it is equally forbidden.
const CLOSING_VERBS = new Set(["task_transition", "complete_task"]);
const claim = (overrides = {}) => ({
  id: "task:1",
  status: "claimed",
  claim_started_at: NOW - 600,
  lease_expires_at: NOW + 600,
  ...overrides,
});
const evidence = {
  schema_version: 1,
  task_id: "task:1",
  agent_id: "session:v1:test",
  started_at: NOW - 600,
  ended_at: NOW,
  changed_node_ids: ["artifact:scripts/canonical-push.mjs"],
  failed_node_ids: [],
  execution_ids: [],
  successful_execution_ids: [],
  commit_ids: ["intent:abc"],
  summary: "one published commit",
  provenance: [],
};

const fixture = (
  check = { id: 7, token: "token", verdict: "aligned", findings: [] },
) => {
  const calls = [];
  const callToolsFn = (server, _root, requested) => {
    calls.push({ server, requested });
    if (server === "memory") return [{ agent_id: "agent" }, evidence];
    if (server === "intent") return [{ agent_id: "agent" }, check];
    throw new Error(`unknown server ${server}`);
  };
  return {
    calls,
    callToolsFn,
    resolveServerFn: (_root, plane) =>
      plane === "mindleak" ? "memory" : "intent",
  };
};

test("an aligned check becomes an exact offer without completing the task", () => {
  const fake = fixture();
  const offer = prepareCompletionOffer({
    repoRoot: "repo",
    sessionId: SESSION,
    claims: [claim()],
    endedAt: NOW,
    ...fake,
  });

  assert.deepEqual(offer, {
    schema: 1,
    task_id: "task:1",
    evidence,
    check: { id: 7, token: "token", verdict: "aligned", findings: [] },
  });
  const names = fake.calls.flatMap(({ requested }) =>
    requested.map(({ name }) => name),
  );
  assert.deepEqual(names, [
    "open_session",
    "evidence_for",
    "open_session",
    "check_conformance",
  ]);
  assert.equal(
    names.some((name) => CLOSING_VERBS.has(name)),
    false,
    "ADR-0065 offers; it never closes",
  );
});

test("a needs_human check is still offered rather than disguised as success", () => {
  const fake = fixture({
    id: 8,
    token: "review",
    verdict: "needs_human",
    findings: ["a person decides"],
  });
  const offer = prepareCompletionOffer({
    repoRoot: "repo",
    sessionId: SESSION,
    claims: [claim()],
    endedAt: NOW,
    ...fake,
  });

  assert.equal(offer.check.verdict, "needs_human");
  assert.match(
    completionOfferNotice(offer, "target/offer.json"),
    /needs_human/,
  );
  // The notice is the instruction an agent follows next, so it has to name a
  // verb the server still advertises. Retired names in guidance are invisible
  // to every other check: nothing imports a sentence.
  assert.match(
    completionOfferNotice(offer, "target/offer.json"),
    /task_transition\(task_id, to="complete"/,
  );
  assert.equal(
    fake.calls
      .flatMap(({ requested }) => requested)
      .some(({ name }) => CLOSING_VERBS.has(name)),
    false,
    "ADR-0065 offers; it never closes, whichever verb would do the closing",
  );
});

test("ambiguity, expiry, and an unavailable plane decline silently", () => {
  for (const claims of [[], [claim(), claim({ id: "task:2" })]]) {
    let called = false;
    assert.equal(
      prepareCompletionOffer({
        repoRoot: "repo",
        sessionId: SESSION,
        claims,
        endedAt: NOW,
        resolveServerFn: () => {
          called = true;
          return "server";
        },
      }),
      null,
    );
    assert.equal(
      called,
      false,
      "no plane is contacted when the task is ambiguous",
    );
  }

  assert.equal(
    prepareCompletionOffer({
      repoRoot: "repo",
      sessionId: SESSION,
      claims: [claim({ lease_expires_at: NOW - 1 })],
      endedAt: NOW,
    }),
    null,
  );
  assert.equal(
    prepareCompletionOffer({
      repoRoot: "repo",
      sessionId: SESSION,
      claims: [claim()],
      endedAt: NOW,
      resolveServerFn: () => null,
    }),
    null,
  );
  assert.equal(
    prepareCompletionOffer({
      repoRoot: "repo",
      sessionId: SESSION,
      claims: [claim()],
      endedAt: NOW,
      resolveServerFn: () => {
        throw new Error("server lookup failed after publication");
      },
    }),
    null,
  );
});

test("a rejected evidence/check call changes nothing about publication", () => {
  const offer = prepareCompletionOffer({
    repoRoot: "repo",
    sessionId: SESSION,
    claims: [claim()],
    endedAt: NOW,
    resolveServerFn: (_root, plane) => plane,
    callToolsFn: () => {
      throw new Error("server unavailable after the push");
    },
  });
  assert.equal(offer, null);
});

test("an empty evidence bundle declines without running a conformance check", () => {
  const calls = [];
  const offer = prepareCompletionOffer({
    repoRoot: "repo",
    sessionId: SESSION,
    claims: [claim()],
    endedAt: NOW,
    resolveServerFn: (_root, plane) => plane,
    callToolsFn: (server, _root, requested) => {
      calls.push({ server, requested });
      if (server === "mindleak") {
        return [
          { agent_id: "agent" },
          {
            ...evidence,
            changed_node_ids: [],
            execution_ids: [],
            commit_ids: [],
            provenance: [],
          },
        ];
      }
      throw new Error("check_conformance must not run for empty evidence");
    },
  });

  assert.equal(offer, null);
  assert.deepEqual(
    calls.map(({ server }) => server),
    ["mindleak"],
  );
});

test("the exact offer is persisted outside Git and named in one bounded notice", () => {
  const offer = {
    schema: 1,
    task_id: "task:1",
    evidence,
    check: { id: 7, token: "token", verdict: "aligned", findings: [] },
  };
  const directories = [];
  const writes = [];
  const path = persistCompletionOffer({
    repoRoot: "repo",
    offer,
    mkdir: (directory, options) => directories.push({ directory, options }),
    write: (destination, contents, encoding) =>
      writes.push({ destination, contents, encoding }),
  });

  assert.equal(path, "target/completion-offers/task-1.json");
  assert.equal(directories[0].options.recursive, true);
  assert.equal(JSON.parse(writes[0].contents).task_id, "task:1");
  assert.equal(writes[0].encoding, "utf8");
  const notice = completionOfferNotice(offer, path);
  assert.match(notice, /submit explicitly/);
  assert.match(notice, /push has already succeeded/);
});
